CREATE FUNCTION count_orders_by_status(p_status TEXT)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE v_count BIGINT;
BEGIN
  EXECUTE 'SELECT count(*) FROM orders WHERE status = $1'
  INTO v_count USING p_status;
  RETURN v_count;
END;
$$;
